CREATE TABLE `centre_land_use_metrics` (
  `centre_id` int unsigned NOT NULL,
  `plan_year` smallint unsigned NOT NULL,
  `buffer_radius_m` smallint unsigned NOT NULL,
  `land_use_category` varchar(100) NOT NULL,
  `zoned_area_m2` decimal(16,2) DEFAULT NULL,
  `land_use_share` decimal(9,6) DEFAULT NULL COMMENT 'Fraction from 0 to 1; not footfall',
  PRIMARY KEY (`centre_id`,`plan_year`,`buffer_radius_m`,`land_use_category`),
  CONSTRAINT `fk_landuse_centre` FOREIGN KEY (`centre_id`) REFERENCES `hawker_centres` (`centre_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_landuse_share` CHECK (((`land_use_share` is null) or (`land_use_share` between 0 and 1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
