--
-- Table structure for table `centre_mrt_access`
--

DROP TABLE IF EXISTS `centre_mrt_access`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `centre_mrt_access` (
  `centre_id` int unsigned NOT NULL,
  `nearest_exit_id` int unsigned DEFAULT NULL,
  `nearest_exit_distance_m` decimal(12,2) DEFAULT NULL COMMENT 'Straight-line metric distance, not walking time',
  `exits_within_500m` int unsigned DEFAULT NULL,
  `stations_within_500m` int unsigned DEFAULT NULL COMMENT 'Count DISTINCT station_name',
  PRIMARY KEY (`centre_id`),
  KEY `fk_access_exit` (`nearest_exit_id`),
  CONSTRAINT `fk_access_centre` FOREIGN KEY (`centre_id`) REFERENCES `hawker_centres` (`centre_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_access_exit` FOREIGN KEY (`nearest_exit_id`) REFERENCES `mrt_exits` (`exit_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

