--
-- Table structure for table `hawker_centres`
--

DROP TABLE IF EXISTS `hawker_centres`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hawker_centres` (
  `centre_id` int unsigned NOT NULL AUTO_INCREMENT,
  `centre_key` varchar(160) DEFAULT NULL COMMENT 'Verified project alias key; not assumed to equal official NEA name',
  `nea_objectid` bigint DEFAULT NULL COMMENT 'NEA GEOJSON OBJECTID (external, not primary key)',
  `centre_name` varchar(255) NOT NULL,
  `address` varchar(500) DEFAULT NULL,
  `postal_code` char(6) DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `nea_status` varchar(120) DEFAULT NULL,
  `number_of_cooked_food_stalls` smallint unsigned DEFAULT NULL,
  `subzone_id` int unsigned DEFAULT NULL,
  `matched_to_nea` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`centre_id`),
  UNIQUE KEY `uq_centre_key` (`centre_key`),
  UNIQUE KEY `uq_nea_objectid` (`nea_objectid`),
  KEY `ix_centre_subzone` (`subzone_id`),
  CONSTRAINT `fk_centre_subzone` FOREIGN KEY (`subzone_id`) REFERENCES `subzones` (`subzone_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

