DROP TABLE IF EXISTS `mrt_exits`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mrt_exits` (
  `exit_id` int unsigned NOT NULL AUTO_INCREMENT,
  `lta_objectid` bigint DEFAULT NULL,
  `station_name` varchar(255) NOT NULL,
  `exit_code` varchar(100) DEFAULT NULL,
  `latitude` decimal(10,7) NOT NULL,
  `longitude` decimal(10,7) NOT NULL,
  `rail_type` varchar(3) DEFAULT NULL COMMENT 'MRT or LRT classification',
  PRIMARY KEY (`exit_id`),
  UNIQUE KEY `uq_lta_objectid` (`lta_objectid`),
  KEY `ix_mrt_station` (`station_name`)
) ENGINE=InnoDB AUTO_INCREMENT=614 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

