--
-- Table structure for table `stall_observations`
--

DROP TABLE IF EXISTS `stall_observations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stall_observations` (
  `observation_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `centre_id` int unsigned NOT NULL,
  `stall_id` bigint unsigned DEFAULT NULL COMMENT 'Nullable until unit_no can be matched',
  `observed_on` date DEFAULT NULL COMMENT 'Original scrape observation date; do not invent',
  `unit_no_raw` varchar(40) DEFAULT NULL,
  `unit_no_normalised` varchar(40) DEFAULT NULL,
  `occupancy_status` varchar(40) DEFAULT NULL COMMENT 'Web directory snapshot, not historical NEA tender status',
  `store_name` varchar(255) DEFAULT NULL,
  `cuisine_raw` varchar(150) DEFAULT NULL,
  `cuisine_category` varchar(150) DEFAULT NULL,
  `price_range_raw` varchar(100) DEFAULT NULL,
  `postal_code_1` char(6) DEFAULT NULL,
  `postal_code_2` char(6) DEFAULT NULL,
  `source_url` varchar(2048) NOT NULL,
  PRIMARY KEY (`observation_id`),
  KEY `ix_obs_centre_cuisine` (`centre_id`,`cuisine_category`),
  KEY `ix_obs_stall_date` (`stall_id`,`observed_on`),
  KEY `fk_obs_stall_centre` (`stall_id`,`centre_id`),
  CONSTRAINT `fk_obs_centre` FOREIGN KEY (`centre_id`) REFERENCES `hawker_centres` (`centre_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_obs_stall_centre` FOREIGN KEY (`stall_id`, `centre_id`) REFERENCES `stalls` (`stall_id`, `centre_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4035 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

