--
-- Table structure for table `stalls`
--

DROP TABLE IF EXISTS `stalls`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stalls` (
  `stall_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `centre_id` int unsigned NOT NULL,
  `stall_no_normalised` varchar(40) NOT NULL COMMENT 'Preserve B1 and alphabetic suffixes',
  PRIMARY KEY (`stall_id`),
  UNIQUE KEY `uq_stall_location` (`centre_id`,`stall_no_normalised`),
  UNIQUE KEY `uq_stall_centre_pair` (`stall_id`,`centre_id`),
  CONSTRAINT `fk_stall_centre` FOREIGN KEY (`centre_id`) REFERENCES `hawker_centres` (`centre_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=285 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

