CREATE TABLE `subzone_population` (
  `subzone_id` int unsigned NOT NULL,
  `census_year` smallint unsigned NOT NULL,
  `resident_population` int unsigned DEFAULT NULL,
  `hdb_population` int unsigned DEFAULT NULL,
