  `hdb_3_room` int unsigned DEFAULT NULL,
  `hdb_4_room` int unsigned DEFAULT NULL,
  `hdb_5_room_executive` int unsigned DEFAULT NULL,
  `condo_other_apartments` int unsigned DEFAULT NULL,
  `landed_properties` int unsigned DEFAULT NULL,
  `other_dwellings` int unsigned DEFAULT NULL,
  PRIMARY KEY (`subzone_id`,`census_year`),
  CONSTRAINT `fk_pop_subzone` FOREIGN KEY (`subzone_id`) REFERENCES `subzones` (`subzone_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
