--
-- Table structure for table `tender_opportunities`
--

DROP TABLE IF EXISTS `tender_opportunities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tender_opportunities` (
  `listing_id` bigint unsigned NOT NULL COMMENT 'v0.3 tender_mysql_ready.csv listing_id',
  `stall_id` bigint unsigned NOT NULL,
  `centre_id` int unsigned NOT NULL,
  `exercise_month` date NOT NULL COMMENT 'First day of month; converts CSV YYYY-MM',
  `tender_open_date` date DEFAULT NULL,
  `tender_close_date` date DEFAULT NULL,
  `stall_no` varchar(40) DEFAULT NULL COMMENT 'Original NEA number',
  `release_category` varchar(40) DEFAULT NULL,
  `trade_marker` varchar(30) DEFAULT NULL,
  `allowed_trade_hint` varchar(255) DEFAULT NULL,
  `approximate_area_m2` decimal(9,2) DEFAULT NULL,
  `area_verified` tinyint(1) NOT NULL DEFAULT '0',
  `electrical_load_amps` decimal(8,2) DEFAULT NULL,
  `electrical_verified` tinyint(1) NOT NULL DEFAULT '0',
  `amr_reference_year` smallint unsigned DEFAULT NULL,
  `median_centre_amr_sgd` decimal(12,2) DEFAULT NULL COMMENT 'Centre reference AMR, not winning bid rent',
  `amr_2023_sgd` decimal(12,2) DEFAULT NULL,
  `amr_2024_sgd` decimal(12,2) DEFAULT NULL,
  `amr_2025_sgd` decimal(12,2) DEFAULT NULL,
  `amr_2026_sgd` decimal(12,2) DEFAULT NULL,
  `cleaning_fee_raw` varchar(200) DEFAULT NULL,
  `cleaning_fee_kind` varchar(40) DEFAULT NULL,
  `cleaning_fee_min_sgd` decimal(12,2) DEFAULT NULL,
  `cleaning_fee_max_sgd` decimal(12,2) DEFAULT NULL,
  `cleaning_fee_strict_lower_bound_sgd` decimal(12,2) DEFAULT NULL,
  `scc_raw` varchar(200) DEFAULT NULL,
  `scc_kind` varchar(40) DEFAULT NULL,
  `scc_min_sgd` decimal(12,2) DEFAULT NULL,
  `scc_max_sgd` decimal(12,2) DEFAULT NULL,
  `scc_strict_lower_bound_sgd` decimal(12,2) DEFAULT NULL,
  `costs_need_review` tinyint(1) NOT NULL DEFAULT '0',
  `needs_review` tinyint(1) NOT NULL DEFAULT '0',
  `raw_stall_token` varchar(120) DEFAULT NULL,
  `stall_note_context` text,
  `source_file` varchar(255) NOT NULL,
  `source_page` smallint unsigned DEFAULT NULL,
  PRIMARY KEY (`listing_id`),
  UNIQUE KEY `uq_tender_stall_month` (`stall_id`,`exercise_month`),
  KEY `ix_tender_centre_month` (`centre_id`,`exercise_month`),
  KEY `ix_tender_month_category` (`exercise_month`,`release_category`),
  KEY `fk_tender_stall_centre` (`stall_id`,`centre_id`),
  CONSTRAINT `fk_tender_centre` FOREIGN KEY (`centre_id`) REFERENCES `hawker_centres` (`centre_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_tender_stall_centre` FOREIGN KEY (`stall_id`, `centre_id`) REFERENCES `stalls` (`stall_id`, `centre_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_amps_positive` CHECK (((`electrical_load_amps` is null) or (`electrical_load_amps` > 0))),
  CONSTRAINT `chk_area_positive` CHECK (((`approximate_area_m2` is null) or (`approximate_area_m2` > 0))),
  CONSTRAINT `chk_cleaning_range` CHECK (((`cleaning_fee_min_sgd` is null) or (`cleaning_fee_max_sgd` is null) or (`cleaning_fee_min_sgd` <= `cleaning_fee_max_sgd`))),
  CONSTRAINT `chk_scc_range` CHECK (((`scc_min_sgd` is null) or (`scc_max_sgd` is null) or (`scc_min_sgd` <= `scc_max_sgd`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

