/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `v_cuisine_mix` AS select `latest`.`centre_id` AS `centre_id`,`latest`.`cuisine_category` AS `cuisine_category`,count(0) AS `observed_stalls`,round((count(0) / sum(count(0)) OVER (PARTITION BY `latest`.`centre_id` ) ),4) AS `share_of_classified_occupied_stalls` from (select `o`.`centre_id` AS `centre_id`,`o`.`unit_no_normalised` AS `unit_no_normalised`,`o`.`occupancy_status` AS `occupancy_status`,`o`.`cuisine_category` AS `cuisine_category`,row_number() OVER (PARTITION BY `o`.`centre_id`,`o`.`unit_no_normalised` ORDER BY `o`.`observed_on` desc,`o`.`observation_id` desc )  AS `obs_rank` from `stall_observations` `o` where (`o`.`unit_no_normalised` is not null)) `latest` where ((`latest`.`obs_rank` = 1) and (`latest`.`occupancy_status` = 'occupied') and (`latest`.`cuisine_category` is not null)) group by `latest`.`centre_id`,`latest`.`cuisine_category` */;
